-- Місця, які додають користувачі: автор, приховування, скарги, межа району.
-- Виконати в SQL Editor проєкту Supabase (повністю, одним запуском).
--
-- Що вже було в places до цієї міграції: source (text, default 'community'),
-- created_at (timestamptz default now()). Тому тут додаються лише created_by та is_hidden.
--
-- Політики інших таблиць (checks, reviews, favorites, profiles, place_photos,
-- sos_requests, device_tokens, storage) НЕ змінюються.

create extension if not exists postgis;

-- ============================================================
-- 1. places: відсутні колонки
-- ============================================================
alter table public.places
  add column if not exists created_by uuid references auth.users(id) on delete set null;
alter table public.places
  add column if not exists is_hidden boolean not null default false;

-- Ідентифікатор нових користувацьких місць генерує сервер (тригер нижче теж його примусово ставить).
alter table public.places alter column id set default ('user-' || gen_random_uuid()::text);

create index if not exists places_created_by_created_at_idx
  on public.places (created_by, created_at desc) where source = 'user';

-- ============================================================
-- 2. Межа Шевченківського району (PostGIS)
-- Дані — той самий результат Nominatim, який бере застосунок
-- (search?q=Шевченківський район, Київ, Україна&polygon_geojson=1&limit=1):
-- OSM relation 1755014, Polygon, 744 вершини, отримано 2026-10-23.
-- ============================================================
create table if not exists public.district_boundary (
  id smallint primary key default 1 check (id = 1),
  name text not null,
  osm_relation_id bigint,
  geom geometry(MultiPolygon, 4326) not null,
  updated_at timestamptz not null default now()
);
alter table public.district_boundary enable row level security;

drop policy if exists "district boundary is publicly readable" on public.district_boundary;
create policy "district boundary is publicly readable" on public.district_boundary
  for select using (true);

insert into public.district_boundary (id, name, osm_relation_id, geom)
