)
on conflict (id) do update
  set name = excluded.name,
      osm_relation_id = excluded.osm_relation_id,
      geom = excluded.geom,
      updated_at = now();

create or replace function public.is_inside_district(p_location geography)
returns boolean
language sql stable
set search_path = public, extensions
as $$
  select exists (
    select 1 from public.district_boundary b
    where ST_Contains(b.geom, p_location::geometry)
  );
$$;

-- ============================================================
-- 3. Правила для користувацьких місць (source = 'user')
-- Коди помилок (SQLSTATE) читає застосунок:
--   MP400 — некоректні поля, MP401 — не ввійшов, MP403 — немає прав,
--   MP404 — точка поза районом, MP429 — перевищено добовий ліміт.
-- ============================================================

-- Кількість місць автора за останню добу. security definer — щоб рахувалися й приховані
-- (RLS ховає їх від самого автора), інакше ліміт можна було б обійти.
create or replace function public.user_places_created_last_day(p_user uuid)
returns integer
language sql stable security definer
set search_path = public, extensions
as $$
  select count(*)::int from public.places
  where source = 'user' and created_by = p_user and p_user = auth.uid()
    and created_at > now() - interval '24 hours';
$$;
revoke all on function public.user_places_created_last_day(uuid) from public, anon;
grant execute on function public.user_places_created_last_day(uuid) to authenticated;

-- Пробіли/переноси рядка -> один пробіл, обрізання країв.
create or replace function public.normalize_place_text(p_text text)
returns text
language sql immutable
as $$
  select btrim(regexp_replace(coalesce(p_text, ''), '\s+', ' ', 'g'));
$$;

-- Валідація вже нормалізованих полів користувацького місця (дзеркало перевірок у застосунку).
create or replace function public.validate_user_place(p_name text, p_address text, p_category text)
returns void
language plpgsql immutable
as $$
begin
  if char_length(p_name) < 3 or char_length(p_name) > 80 then
    raise exception using errcode = 'MP400', message = 'Назва має містити від 3 до 80 символів';
  end if;
  if char_length(p_address) > 200 then
    raise exception using errcode = 'MP400', message = 'Адреса задовга (до 200 символів)';
  end if;
  if p_name ~ '[[:cntrl:]]' or p_address ~ '[[:cntrl:]]' then
    raise exception using errcode = 'MP400', message = 'Текст містить недопустимі символи';
  end if;
  if p_category is null or p_category not in ('education', 'health', 'culture', 'sport', 'cafe', 'services', 'admin', 'shop', 'transit') then
    raise exception using errcode = 'MP400', message = 'Оберіть категорію зі списку';
  end if;
end;
$$;

create or replace function public.places_before_insert()
returns trigger
language plpgsql
set search_path = public, extensions
as $$
begin
  if new.source is distinct from 'user' then
    -- OSM-імпорт: лише не даємо клієнту одразу створити прихований запис.
    if current_user in ('authenticated', 'anon') then
      new.is_hidden := false;
    end if;
    return new;
  end if;

  if auth.uid() is null or new.created_by is distinct from auth.uid() then
    raise exception using errcode = 'MP401', message = 'Увійдіть, щоб додавати місця';
  end if;

  new.name := public.normalize_place_text(new.name);
  new.address := public.normalize_place_text(new.address);
  new.verified_note := '';
  perform public.validate_user_place(new.name, new.address, new.category);

  new.id := 'user-' || gen_random_uuid()::text;
  new.status := 'unverified';
  new.is_hidden := false;
  new.created_at := now();
  new.rating := null;
  new.review_count := 0;

  if not public.is_inside_district(new.location) then
    raise exception using errcode = 'MP404', message = 'Місце за межами району';
  end if;

  -- Серіалізуємо вставки одного автора, щоб паралельні запити не обійшли ліміт.
  perform pg_advisory_xact_lock(hashtextextended('places_user_limit:' || new.created_by::text, 0));
  if public.user_places_created_last_day(new.created_by) >= 10 then
    raise exception using errcode = 'MP429', message = 'Можна додати не більше 10 місць за добу';
  end if;

  return new;
end;
$$;

-- Оновлення: зміст користувацького місця (назва, категорія, адреса, позиція) змінює лише автор.
-- Статус доступності й паркування після перевірки за 7 критеріями оновлює будь-хто
-- авторизований — так працює наявна швидка перевірка, тож політику UPDATE не звужуємо,
-- а обмежуємо колонки тут. Тригер — security invoker: коли оновлення робить
-- security definer-функція (приховування через скарги), current_user = власник, і обмеження не діють.
create or replace function public.places_before_update()
returns trigger
language plpgsql
set search_path = public, extensions
as $$
begin
  if current_user in ('authenticated', 'anon') then
    if new.id is distinct from old.id
       or new.source is distinct from old.source
       or new.created_by is distinct from old.created_by
       or new.created_at is distinct from old.created_at
       or new.is_hidden is distinct from old.is_hidden then
      raise exception using errcode = 'MP403', message = 'Ці поля змінювати не можна';
    end if;

    if old.source = 'user'
       and old.created_by is distinct from auth.uid()
       and (new.name is distinct from old.name
            or new.address is distinct from old.address
            or new.category is distinct from old.category
            or new.location is distinct from old.location) then
      raise exception using errcode = 'MP403', message = 'Змінювати можна лише власні місця';
    end if;
  end if;

  if new.source = 'user' then
    new.name := public.normalize_place_text(new.name);
    new.address := public.normalize_place_text(new.address);
    new.verified_note := coalesce(new.verified_note, '');
    perform public.validate_user_place(new.name, new.address, new.category);
    if new.location is distinct from old.location and not public.is_inside_district(new.location) then
      raise exception using errcode = 'MP404', message = 'Місце за межами району';
    end if;
  end if;

  return new;
end;
$$;

drop trigger if exists places_before_insert on public.places;
create trigger places_before_insert
  before insert on public.places
  for each row execute function public.places_before_insert();

drop trigger if exists places_before_update on public.places;
create trigger places_before_update
  before update on public.places
  for each row execute function public.places_before_update();

-- ============================================================
-- 4. RLS для places
-- ============================================================

-- Читання: усі бачать лише неприховані місця.
drop policy if exists "places are publicly readable" on public.places;
drop policy if exists "visible places are publicly readable" on public.places;
create policy "visible places are publicly readable" on public.places
  for select using (is_hidden = false);

-- Вставка: користувацькі місця — лише від свого імені й з source = 'user'.
drop policy if exists "authenticated users can add places" on public.places;
drop policy if exists "users add their own places" on public.places;
create policy "users add their own places" on public.places
  for insert to authenticated
  with check (source = 'user' and created_by = auth.uid());

-- Збережено можливість наявного OSM-імпорту (ImportOsmPlaces): лише source = 'osm', без автора.
drop policy if exists "osm import adds osm places" on public.places;
create policy "osm import adds osm places" on public.places
  for insert to authenticated
  with check (source = 'osm' and created_by is null and id like 'osm-%');

-- Оновлення: наявна політика "authenticated users can update places" лишається
-- (нею користується швидка перевірка для статусу). Зміст чужих користувацьких місць
-- захищає тригер places_before_update.

-- Видалення: лише автор власних користувацьких місць.
drop policy if exists "authors delete their own places" on public.places;
create policy "authors delete their own places" on public.places
  for delete to authenticated
  using (source = 'user' and created_by = auth.uid());

-- Видалення з пов'язаними даними. На місце посилаються checks/reviews/favorites/place_photos
-- без ON DELETE CASCADE, тож простий DELETE упав би, щойно хтось пройшов перевірку.
-- Функція перевіряє авторство сама й прибирає залежні рядки.
create or replace function public.delete_own_place(p_place_id text)
returns void
language plpgsql security definer
set search_path = public, extensions
as $$
begin
  if auth.uid() is null then
    raise exception using errcode = 'MP401', message = 'Увійдіть, щоб видаляти місця';
  end if;
  if not exists (
    select 1 from public.places
    where id = p_place_id and source = 'user' and created_by = auth.uid()
  ) then
    raise exception using errcode = 'MP403', message = 'Видаляти можна лише власні місця';
  end if;

  delete from public.checks where place_id = p_place_id;
  delete from public.reviews where place_id = p_place_id;
  delete from public.favorites where place_id = p_place_id;
  delete from public.place_photos where place_id = p_place_id;
  delete from public.places where id = p_place_id;
end;
$$;
revoke all on function public.delete_own_place(text) from public, anon;
grant execute on function public.delete_own_place(text) to authenticated;

-- ============================================================
-- 5. Скарги
-- ============================================================
create table if not exists public.place_reports (
  id uuid primary key default gen_random_uuid(),
  place_id text not null references public.places(id) on delete cascade,
  reporter_id uuid not null default auth.uid() references auth.users(id) on delete cascade,
  reason text not null check (reason in ('duplicate', 'wrong_location', 'not_exists', 'other')),
  comment text check (comment is null or char_length(comment) <= 500),
  created_at timestamptz not null default now(),
  constraint place_reports_one_per_user unique (place_id, reporter_id)
);
alter table public.place_reports enable row level security;

drop policy if exists "users read their own reports" on public.place_reports;
create policy "users read their own reports" on public.place_reports
  for select to authenticated
  using (reporter_id = auth.uid());

-- Скаржитися можна лише на чужі користувацькі місця.
drop policy if exists "users report other users places" on public.place_reports;
create policy "users report other users places" on public.place_reports
  for insert to authenticated
  with check (
    reporter_id = auth.uid()
    and exists (
      select 1 from public.places p
      where p.id = place_id
        and p.source = 'user'
        and p.created_by is distinct from auth.uid()
    )
  );

-- 3 скарги від різних користувачів — місце ховається.
create or replace function public.place_reports_hide_place()
returns trigger
language plpgsql security definer
set search_path = public, extensions
as $$
begin
  if (select count(distinct reporter_id) from public.place_reports where place_id = new.place_id) >= 3 then
    update public.places set is_hidden = true where id = new.place_id and is_hidden = false;
  end if;
  return new;
end;
$$;

drop trigger if exists place_reports_hide_place on public.place_reports;
create trigger place_reports_hide_place
  after insert on public.place_reports
  for each row execute function public.place_reports_hide_place();
